$bytes = [System.IO.File]::ReadAllBytes("$PWD\index.html")
$text = [System.Text.Encoding]::UTF8.GetString($bytes)

$b64 = ''
$jsonBytes = [Convert]::FromBase64String($b64)
$jsonStr = [System.Text.Encoding]::UTF8.GetString($jsonBytes)
$replacements = $jsonStr | ConvertFrom-Json

foreach ($prop in $replacements.psobject.properties) {
    $text = $text.Replace($prop.Name, $prop.Value)
}

# Safely delete remparts and mellah
$text = [regex]::Replace($text, '(?s)[ \t]*<div class="city-card">\s*<div class="city-card-img-wrap">\s*<img src="images/essaouira/remparts\.jpg".*?</div>\s*<h3>Les remparts.*?</h3>.*?</div>\s*', "")
$text = [regex]::Replace($text, '(?s)[ \t]*<div class="city-card">\s*<div class="city-card-img-wrap">\s*<img src="images/essaouira/mellah\.jpg".*?</div>\s*<h3>Le Mellah</h3>.*?</div>\s*', "")

$utf8NoBom = New-Object System.Text.UTF8Encoding $false
[System.IO.File]::WriteAllText("$PWD\index.html", $text, $utf8NoBom)
Write-Output "Essaouira safely mapped via Base64!"
